sys_script_include.script:
var SubmissionBuilder = Class.create();
SubmissionBuilder.prototype = {
    initialize: function() {
        this.SUBMISSION = 'x_gegis_ins_policy_submission';
        this.LINE = 'x_gegis_ins_policy_submission_line';
        this.ENTITY = 'x_gegis_ins_policy_extraction_entity';
    },

    /**
     * Create the submission header + one line per LOB entity, link the
     * extraction to it, then delegate field population to ExtractionApplier.
     *
     * @param extractionGr GlideRecord x_gegis_ins_policy_extraction
     * @return String sys_id of the created submission
     */
    buildFromExtraction: function(extractionGr) {
        var sub = new GlideRecord(this.SUBMISSION);
        sub.initialize();
        sub.state = 'received';
        sub.extraction_status = 'pending_review';
        sub.received_date = new GlideDateTime();
        sub.source_channel = String(extractionGr.source) || 'api';
        sub.current_extraction = extractionGr.getUniqueValue();
        sub.overall_confidence = extractionGr.confidence_overall;
        sub.requires_review = true;
        var subId = sub.insert();

        extractionGr.submission = subId;
        extractionGr.update();

        this._buildLines(extractionGr, subId);
        new x_gegis_ins_policy.ExtractionApplier().apply(extractionGr);
        return subId;
    },

    /** One submission_line per accepted submission_line entity. */
    _buildLines: function(extractionGr, subId) {
        var e = new GlideRecord(this.ENTITY);
        e.addQuery('extraction', extractionGr.getUniqueValue());
        e.addQuery('entity_type', 'submission_line');
        e.addQuery('disposition', '!=', 'rejected');
        e.orderBy('entity_index');
        e.query();
        while (e.next()) {
            var line = new GlideRecord(this.LINE);
            line.initialize();
            line.submission = subId;
            line.state = 'pending';
            var lineId = line.insert();
            e.matched_table = this.LINE;
            e.matched_record = lineId;
            e.match_status = 'matched';
            e.update();
        }
    },

    type: 'SubmissionBuilder'
};
